const fs = require('fs');
const path = require('path');

const WORKSPACE = __dirname;
const MANIFEST_PATH = path.join(WORKSPACE, 'backup-manifest.json');

const entries = fs.readdirSync(WORKSPACE, { withFileTypes: true });

const sourceFiles = entries
    .filter((entry) => entry.isFile())
    .filter((entry) => !entry.name.startsWith('.'))
    .filter((entry) => entry.name !== 'backup-manifest.json')
    .filter((entry) => entry.name !== 'backup.js')
    .filter((entry) => entry.name !== 'README.md')
    .map((entry) => entry.name)
    .sort();

const manifest = {
    files: sourceFiles,
};

fs.writeFileSync(MANIFEST_PATH, JSON.stringify(manifest, null, 2) + '\n');

console.log(`Wrote ${sourceFiles.length} files to backup-manifest.json`);
console.log(sourceFiles);

